+inline __device__ unsigned prmt(unsigned hi, unsigned lo, unsigned select_code) {
+  unsigned res = 0;
+  asm volatile(
+      "{\n"
+      "prmt.b32 %0, %1, %2, %3;\n"
+      "}\n"
+      : "=r"(res)
+      : "r"(lo), "r"(hi), "r"(select_code));
+  return res;
+}
