+        int64_t const channel_extent = static_cast<int64_t>(cute::get<0>(problem));
+        host_shapes_match = host_shapes_match && channel_extent == args.output_channel_extent &&
+                            (channel_extent % RequiredChannelMultiple) == 0;
+      }
