+    CUTLASS_HOST_DEVICE
+    bool is_valid() const {
+      return is_valid_tile != 0;
+    }
+
+    CUTLASS_HOST_DEVICE
+    static WorkTileInfo invalid_work_tile() {
+      return {-1, -1, -1, 0};
+    }
+
+    CUTLASS_HOST_DEVICE
+    bool is_final_split(uint32_t k_tiles_per_output_tile) const {
