+  const float scale_inv = scale == 0.0f ? 0.0f : 1.0f / scale;
+  for (int32_t i = tid; i < num_vec_elems; i += blockDim.x) {
+    vec_t input_vec;
+    input_vec.cast_load(token_input + i * kVecSize);
+    DST_DTYPE output_arr[kVecSize];
